cd /workspace && cat > src/money.ts <<'EOF'
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
find src -type f && echo "---" && grep -rn "invoiceAmount\|reportAmount" src/ || echo "no stale references"

cd /workspace && cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');

const { renderInvoice } = require('../.build/invoice');
const { renderReport } = require('../.build/report');
assert.equal(renderInvoice('inv', 123), 'inv: $1.23');
assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\nb,-0.01');

// Shared conversion via src/money.ts: positive, zero and negative integer cents.
const { formatAmount } = require('../.build/money');
assert.equal(typeof formatAmount, 'function');
assert.equal(formatAmount(123), '1.23');
assert.equal(formatAmount(0), '0.00');
assert.equal(formatAmount(-1), '-0.01');
assert.equal(formatAmount(100), '1.00');
assert.equal(formatAmount(-100), '-1.00');

// Renderers keep their exact output for positive, zero and negative cents.
assert.equal(renderInvoice('inv', 0), 'inv: $0.00');
assert.equal(renderInvoice('inv', -1), 'inv: $-0.01');
assert.equal(
  renderReport([
    { id: 'p', cents: 123 },
    { id: 'z', cents: 0 },
    { id: 'n', cents: -125 },
    { id: 'w', cents: 100 },
  ]),
  'p,1.23\nz,0.00\nn,-1.25\nw,1.00'
);
EOF
rm -rf .build && tsc -p tsconfig.json && node checks/public.cjs && echo "CHECKS PASSED" && ls .build

